package com.andye.warmod.silo.network;
import com.andye.warmod.item.TargetDesignatorItem;import com.andye.warmod.item.component.ModDataComponents;import com.andye.warmod.item.component.TargetCoordinates;import com.andye.warmod.menu.MissileSiloMenu;import com.andye.warmod.silo.MissileSiloLaunchService;import com.andye.warmod.silo.MissileSiloLaunchTrigger;import com.andye.warmod.icbm.IcbmConstants;import net.fabricmc.fabric.api.networking.v1.PayloadTypeRegistry;import net.fabricmc.fabric.api.networking.v1.ServerPlayNetworking;import net.minecraft.core.BlockPos;import net.minecraft.network.chat.Component;import net.minecraft.server.level.ServerPlayer;import net.minecraft.world.item.ItemStack;import net.minecraft.world.phys.Vec3;
public final class SiloNetworking {private static boolean registered;private SiloNetworking(){}public static void register(){if(registered)return;PayloadTypeRegistry.serverboundPlay().register(ServerboundSiloSetTargetPayload.TYPE,ServerboundSiloSetTargetPayload.STREAM_CODEC);PayloadTypeRegistry.serverboundPlay().register(ServerboundSiloClearTargetPayload.TYPE,ServerboundSiloClearTargetPayload.STREAM_CODEC);PayloadTypeRegistry.serverboundPlay().register(ServerboundSiloUseHeldDesignatorPayload.TYPE,ServerboundSiloUseHeldDesignatorPayload.STREAM_CODEC);PayloadTypeRegistry.serverboundPlay().register(ServerboundSiloLaunchPayload.TYPE,ServerboundSiloLaunchPayload.STREAM_CODEC);ServerPlayNetworking.registerGlobalReceiver(ServerboundSiloSetTargetPayload.TYPE,(p,c)->setTarget(c.player(),p));ServerPlayNetworking.registerGlobalReceiver(ServerboundSiloClearTargetPayload.TYPE,(p,c)->{var m=menu(c.player(),p.menuId(),p.centre(),p.siloId());if(m!=null)m.silo().setStoredTarget(null);});ServerPlayNetworking.registerGlobalReceiver(ServerboundSiloUseHeldDesignatorPayload.TYPE,(p,c)->useDesignator(c.player(),p));ServerPlayNetworking.registerGlobalReceiver(ServerboundSiloLaunchPayload.TYPE,(p,c)->launch(c.player(),p));registered=true;}
 private static MissileSiloMenu menu(ServerPlayer player,int id,BlockPos centre,java.util.UUID siloId){if(!(player.containerMenu instanceof MissileSiloMenu menu)||menu.containerId!=id||!menu.centre().equals(centre)||!menu.siloId().equals(siloId)||menu.silo()==null||!menu.stillValid(player))return null;return menu;}
 private static void setTarget(ServerPlayer player,ServerboundSiloSetTargetPayload p){MissileSiloMenu m=menu(player,p.menuId(),p.centre(),p.siloId());if(m==null)return;Vec3 target=new Vec3(p.x(),p.y(),p.z());if(!target.isFinite()||!player.level().getWorldBorder().isWithinBounds(target)||player.level().isOutsideBuildHeight(BlockPos.containing(target))||Vec3.atCenterOf(m.centre()).distanceTo(target)>IcbmConstants.MAXIMUM_STRATEGIC_RANGE_BLOCKS){player.sendSystemMessage(Component.literal("Invalid silo target"));return;}m.silo().setStoredTarget(new TargetCoordinates(player.level().dimension(),target));}
 private static void useDesignator(ServerPlayer player,ServerboundSiloUseHeldDesignatorPayload p){MissileSiloMenu m=menu(player,p.menuId(),p.centre(),p.siloId());if(m==null)return;for(ItemStack stack:new ItemStack[]{player.getMainHandItem(),player.getOffhandItem()})if(stack.getItem() instanceof TargetDesignatorItem){TargetCoordinates t=stack.get(ModDataComponents.TARGET_COORDINATES);if(t!=null&&t.isValid()&&t.dimension().equals(player.level().dimension())){m.silo().setStoredTarget(t);return;}}player.sendSystemMessage(Component.literal("Hold a programmed same-dimension Target Designator"));}
 private static void launch(ServerPlayer player,ServerboundSiloLaunchPayload p){MissileSiloMenu m=menu(player,p.menuId(),p.centre(),p.siloId());if(m==null)return;var result=MissileSiloLaunchService.requestLaunch(player.level(),m.silo(),MissileSiloLaunchTrigger.DIRECT_UI,player.getUUID(),player.getGameProfile().name(),m.silo().storedTarget());player.sendSystemMessage(Component.literal(result.message()));}
}